globalThis.DLRewardAdventure={"start": {"text": "Du bist mit einer Freundin im Park. Auf einer Bank liegt eine Karte mit einem Stern. Welchen Weg möchtet ihr gemeinsam gehen?", "choices": [["Zum Teich", "pond"], ["Zum Garten", "garden"]]}, "pond": {"text": "Am Teich schwimmt eine Ente. Auf der Karte steht das Wort Brücke. Was möchtet ihr als Nächstes tun?", "choices": [["Zur Brücke gehen", "bridge"], ["Die Karte noch einmal lesen", "look"]]}, "garden": {"text": "Im Garten stehen gelbe Blumen. Eine Gärtnerin zeigt auf ein kleines Regal. Was interessiert euch?", "choices": [["Das Regal ansehen", "books"], ["Die Gärtnerin nach den Blumen fragen", "flowers"]]}, "bridge": {"text": "Auf der Brücke trefft ihr einen Freund mit einem Skizzenbuch. Gemeinsam zeichnet ihr die Ente. Euer Weg endet mit einem neuen Bild.", "choices": []}, "look": {"text": "Auf der Rückseite steht eine Einladung zu einer Lesestunde. Ihr geht mit eurer Freundin zur Parkbibliothek. Ein ruhiger Nachmittag mit Geschichten beginnt.", "choices": []}, "books": {"text": "Im Regal stehen Bücher zum Tauschen. Ihr sucht eine Tiergeschichte aus und bringt später ein eigenes Buch zurück. Aus der Karte wird ein neues Leseabenteuer.", "choices": []}, "flowers": {"text": "Die Gärtnerin erklärt, wie man Blumen gießt. Ihr helft mit einer kleinen Gießkanne. Zum Abschied zeigt sie euch eine neue Knospe.", "choices": []}};

